"use client";

import "./field.css";
import { Field as BaseField } from "@base-ui/react/field";
import type React from "react";
import { cn } from "tailwind-variants";

import { FieldContext, useFieldContext } from "./field.context";
import { fieldVariants, type FieldVariants } from "./field.variants";

export type FieldProps = FieldVariants & React.ComponentProps<typeof BaseField.Root>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/field/content.md
 */
export const FieldRoot = ({ children, className, size, ...props }: FieldProps) => {
  const slots = fieldVariants({ size });

  return (
    <FieldContext.Provider value={{ slots }}>
      <BaseField.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseField.Root>
    </FieldContext.Provider>
  );
};

export type FieldLabelProps = React.ComponentProps<typeof BaseField.Label>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/field/content.md
 */
export const FieldLabel = ({ className, ...props }: FieldLabelProps) => {
  const { slots } = useFieldContext();
  return <BaseField.Label className={cn(slots.label(), className)} {...props} />;
};

export type FieldControlProps = React.ComponentProps<typeof BaseField.Control>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/field/content.md
 */
export const FieldControl = ({ className, ...props }: FieldControlProps) => {
  const { slots } = useFieldContext();
  return <BaseField.Control className={cn(slots.control(), className)} {...props} />;
};

export type FieldErrorProps = React.ComponentProps<typeof BaseField.Error>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/field/content.md
 */
export const FieldError = ({ className, ...props }: FieldErrorProps) => {
  const { slots } = useFieldContext();
  return <BaseField.Error className={cn(slots.error(), className)} {...props} />;
};

export type FieldDescriptionProps = React.ComponentProps<typeof BaseField.Description>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/field/content.md
 */
export const FieldDescription = ({ className, ...props }: FieldDescriptionProps) => {
  const { slots } = useFieldContext();
  return <BaseField.Description className={cn(slots.description(), className)} {...props} />;
};

export type FieldItemProps = React.ComponentProps<typeof BaseField.Item>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/field/content.md
 */
export const FieldItem = ({ className, ...props }: FieldItemProps) => {
  const { slots } = useFieldContext();
  return <BaseField.Item className={cn(slots.item(), className)} {...props} />;
};

export type FieldValidityProps = React.ComponentProps<typeof BaseField.Validity>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/field/content.md
 */
export const FieldValidity = (props: FieldValidityProps) => {
  return <BaseField.Validity {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const fieldVariants = tv({
  slots: {
    root: "field",
    label: "field__label",
    control: "field__control",
    error: "field__error",
    description: "field__description",
    item: "field__item",
  },
  variants: {
    size: {
      sm: {
        label: "field__label--sm",
        control: "field__control--sm",
      },
      md: {
        label: "field__label--md",
        control: "field__control--md",
      },
      lg: {
        label: "field__label--lg",
        control: "field__control--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type FieldVariants = VariantProps<typeof fieldVariants>;

"use client";

import { createContext, useContext } from "react";

import { fieldVariants } from "./field.variants";

export type FieldContext = {
  slots: ReturnType<typeof fieldVariants>;
};

export const FieldContext = createContext<FieldContext | null>(null);

export const useFieldContext = () => {
  const context = useContext(FieldContext);
  return context ?? { slots: fieldVariants() };
};

.field {
  @apply text-foreground flex w-full flex-col items-start gap-1.5;
}

.field__label {
  @apply text-foreground data-invalid:text-destructive text-sm font-medium select-none data-disabled:opacity-50;
}

.field__control {
  @apply border-input bg-background placeholder:text-muted-foreground focus-visible:outline-ring data-invalid:border-destructive data-invalid:focus-visible:outline-destructive h-9 w-full rounded-md border px-3 py-1 text-sm shadow-xs transition-colors focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50;
}

.field__error {
  @apply text-destructive text-xs font-medium transition-all duration-150 data-ending-style:opacity-0 data-starting-style:opacity-0;
}

.field__description {
  @apply text-muted-foreground text-xs;
}

.field__item {
  @apply flex items-center gap-2;
}

import {
  FieldControl,
  FieldDescription,
  FieldError,
  FieldItem,
  FieldLabel,
  FieldRoot,
  FieldValidity,
} from "./field";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/field/content.md
 */
export const Field = {
  Control: FieldControl,
  Description: FieldDescription,
  Error: FieldError,
  Item: FieldItem,
  Label: FieldLabel,
  Root: FieldRoot,
  Validity: FieldValidity,
};

export {
  FieldControl,
  FieldDescription,
  FieldError,
  FieldItem,
  FieldLabel,
  FieldRoot,
  FieldValidity,
};

export type {
  FieldControlProps,
  FieldDescriptionProps,
  FieldErrorProps,
  FieldItemProps,
  FieldLabelProps,
  FieldProps,
  FieldValidityProps,
} from "./field";
export { FieldContext, useFieldContext } from "./field.context";
export { type FieldVariants, fieldVariants } from "./field.variants";
